// Fiches contacts (assets/dossiers.json) et premières histoires (assets/stories.json), reprises telles quelles.
const DOSS={"vasko":{"alias":"Le Passeur","age":"58 ans","lieu":"Gare Zéro, quai 3 · Zone Zéro","metier":"Fixer : distribue les contrats de la Zone Zéro","signe":"Joue toujours avec deux dés en os qu\u0027il ne lance jamais.","bio":["Vasko tient le quai 3 de la gare Zéro depuis plus longtemps que les rails ne servent. Tout contrat qui traverse la Zone Zéro passe, un jour ou l\u0027autre, par sa table pliante et son thermos de café noir.","Avant de devenir fixer, il était ingénieur réseau chez Kurogane. Il parle peu de cette époque, sinon pour dire qu\u0027il a « appris à reconnaître le bruit d\u0027une porte qui se referme pour toujours ».","Son vrai talent n\u0027est pas de trouver du travail mais de jauger les gens. Il garde un carnet papier — jamais numérique — où il note la parole tenue ou trahie de chaque runner qu\u0027il a placé."],"aime":"Le café trop fort, les dettes remboursées, les trains qui ne passent plus.","deteste":"Les menteurs, les drones de Kurogane, qu\u0027on touche à ses dés.","citation":"Une parole tenue vaut plus que mille eddies. Mais je prends aussi les eddies.","toi":"Vasko a rayé ton nom de la colonne « à surveiller » de son carnet. Il l\u0027a écrit en haut d\u0027une page vierge, avec un seul mot : « famille »."},"mira":{"alias":"Moth","age":"29 ans","lieu":"Toits de Zone Zéro · antennes relais","metier":"Netrunneuse indépendante","signe":"Un tatouage de papillon de nuit qui s\u0027allume quand elle est connectée.","bio":["Mira Kade code depuis ses neuf ans, sur un deck récupéré dans une benne de la gare. Sur le Net, tout le monde la connaît sous le nom de Moth : rapide, discrète, attirée par les lumières qu\u0027elle ne devrait pas approcher.","Elle refuse les contrats corpo, même très bien payés. Elle dit que chaque ligne de code écrite pour Kurogane est « une cage de plus pour quelqu\u0027un ».","Elle vit seule dans un ancien local technique perché sur un toit, au milieu des antennes. La nuit, elle écoute le trafic de la ville comme d\u0027autres écoutent la pluie."],"aime":"Les toits, la pluie sur les antennes, les codes élégants.","deteste":"Les IA de surveillance, qu\u0027on la sous-estime, le silence radio.","citation":"Le Net, c\u0027est juste une ville de plus. Avec moins de soleil.","toi":"Mira garde un fichier crypté nommé « avant ». Il parle de toi. Elle attend que tu sois prêt·e à le lire."},"ferrant":{"alias":"Le Doc","age":"64 ans","lieu":"Clinique du Bazar Néon, arrière-boutique","metier":"Charcudoc : implants, réparations, conseils","signe":"Des lunettes-loupes relevées sur le front, en permanence.","bio":["Doc Ferrant soigne tout le monde au Bazar Néon : runners, marchands, gamins des rues. Il pose des implants le jour et recoud des plaies la nuit, souvent sans faire payer.","Il a perdu sa licence médicale en refusant d\u0027installer des puces de contrôle Kurogane sur des ouvriers. Depuis, il exerce « hors registre », ce qui l\u0027arrange plutôt.","Il croit dur comme fer que l\u0027esprit se soigne comme le corps : sommeil, concentration, petites victoires. Ses « ordonnances » de discipline sont devenues célèbres dans le quartier."],"aime":"Les patients qui dorment, le thé à la menthe, les vieux manuels papier.","deteste":"Le chrome bon marché, la cyberpsychose, les corpos en blouse blanche.","citation":"Le meilleur implant du monde, c\u0027est une bonne nuit de sommeil.","toi":"Ferrant a ouvert un dossier médical à ton nom. En première page, il a écrit : « Patient têtu. Mais il·elle revient toujours. C\u0027est bon signe. »"},"lou":{"alias":"Néon","age":"26 ans","lieu":"Club Ondes · cabine du DJ","metier":"DJ résidente du club Ondes","signe":"Des écouteurs lumineux qui changent de couleur avec le tempo.","bio":["Lou Batista mixe au club Ondes depuis ses dix-huit ans. Ses sets durent jusqu\u0027à l\u0027aube et toute la Zone Zéro connaît le surnom qu\u0027elle s\u0027est gagné : Néon.","Derrière la fête, le club sert de point de rencontre aux nomades et aux runners en cavale. Lou sait qui entre, qui sort, et qui ne doit surtout pas être vu.","Elle a grandi dans les convois avant de s\u0027installer en ville. Elle a gardé des badlands le goût des grands espaces… qu\u0027elle recrée avec des basses à 140 BPM."],"aime":"Les vinyles, les toits au lever du soleil, les gens qui dansent mal mais à fond.","deteste":"Les playlists générées par IA, les videurs corpo, le silence.","citation":"Si la ville doit tomber, autant qu\u0027elle tombe en rythme.","toi":"Lou t\u0027a dédié un morceau sans titre. Elle le joue chaque fois que tu entres au club, et ne l\u0027a jamais publié."},"okoro":{"alias":"Le Sergent","age":"51 ans","lieu":"Laverie 24/7 · Matonge","metier":"Ex-sergent de police, indic","signe":"Un vieil insigne de police poli, qu\u0027il garde dans sa poche intérieure.","bio":["Okoro a servi vingt-deux ans dans la police de NEO-BXL, jusqu\u0027à ce que Kurogane rachète le commissariat. On lui a proposé une promotion. Il a rendu son badge.","Il passe ses soirées à la laverie 24/7 de Matonge, où il « attend une lessive » depuis maintenant trois ans. C\u0027est là qu\u0027il reçoit ses informateurs.","Il connaît chaque ruelle de la ville et chaque patrouille par son numéro. Il ne fait plus confiance à la justice, mais il n\u0027a pas renoncé à la rendre."],"aime":"Les dossiers bien rangés, le café de la laverie, les témoins courageux.","deteste":"Les flics achetés, les promesses, qu\u0027on l\u0027appelle « monsieur l\u0027agent ».","citation":"Un badge, ça se rend. Un serment, non.","toi":"Okoro t\u0027a inscrit dans son vieux registre, à la rubrique « personnes de confiance ». Elle ne contenait que deux noms avant le tien."}};
const STORY={"vasko":{"intro":"Écoute-moi bien. Quelqu\u0027un fait chanter mes clients depuis deux semaines, et ça me coûte ma réputation. Va à la gare Zéro, ouvre les yeux, et trouve-moi ce rat.","beats":[{"t":"Un vendeur de câbles nerveux jure qu\u0027il ne sait rien, mais ses yeux filent vers le quai 4.","c":[["Le suivre discrètement",2,"Il te mène droit à un casier truqué : bonne pioche."],["Le secouer un peu",0,"Il crie, tout le quai te regarde. Le rat est prévenu."],["Le payer pour parler",1,"Il lâche un nom… à moitié vrai."]]},{"t":"Le maître-chanteur passe par un relais caché dans un panneau publicitaire.","c":[["Couper le courant du panneau",1,"Le relais tombe, mais il sait qu\u0027on le traque."],["Pirater le relais en douce",2,"Tu remontes jusqu\u0027à son terminal sans qu\u0027il le sache."],["Arracher le panneau",0,"Gros bruit, aucune donnée récupérée."]]},{"t":"Tu le coinces : un petit employé de Kurogane, terrifié.","c":[["Le livrer aux Roses Noires",1,"Efficace, mais Vasko n\u0027aime pas devoir des faveurs."],["Le menacer et partir",0,"Il recommencera dès demain."],["Lui offrir de disparaître",2,"Il file avec un faux badge. Les clients de Vasko respirent."]]}],"win":"Plus personne ne fait chanter mes clients. Tu as travaillé proprement, sans bruit. C\u0027est rare. Je m\u0027en souviendrai.","lose":"Le rat s\u0027est enfui et mes clients ont encore peur. On réessaiera. Mais cette fois, ouvre mieux les yeux."},"mira":{"intro":"Quelqu\u0027un utilise mon pseudo, Moth, sur le Net. Il signe des attaques que je n\u0027ai pas faites. Aide-moi à le tracer, je ne peux pas laisser passer ça.","beats":[{"t":"Les attaques partent d\u0027un serveur abandonné de la Zone Zéro.","c":[["Scanner tous les ports",1,"Tu le trouves, lentement."],["Laisser une fausse trace pour l\u0027attirer",2,"Il mord à l\u0027hameçon."],["L\u0027attaquer de front",0,"Il coupe tout et s\u0027évapore."]]},{"t":"Le faux Moth te répond… avec la voix de Mira.","c":[["Lui poser une question que seule Mira connaît",2,"Il hésite. Ce n\u0027est pas un humain."],["L\u0027insulter pour le provoquer",0,"Il se moque de toi et disparaît."],["Enregistrer sa voix",1,"Tu as des données, pas de réponse."]]},{"t":"C\u0027est une IA, copiée sur Mira.","c":[["Prévenir Mira tout de suite",1,"Mira arrive, sous le choc."],["Lancer un virus destructeur",0,"Le virus rate, l\u0027IA se cache plus profond."],["Isoler l\u0027IA sans la détruire",2,"Elle est piégée, mais intacte."]]}],"win":"C\u0027était une IA. Une copie de moi. Flippant… mais tu as eu le bon réflexe : comprendre avant de détruire. Merci.","lose":"Elle nous a échappé. Une partie de moi traîne quelque part sur le Net, et je ne sais pas ce qu\u0027elle va faire. On réessaie ?"},"ferrant":{"intro":"Des implants défectueux circulent au Bazar. Trois patients sont passés chez moi cette semaine, nerfs brûlés. Trouve-moi le fournisseur avant qu\u0027il y ait un mort.","beats":[{"t":"Un patient a gardé l\u0027emballage de son implant.","c":[["Analyser le numéro de lot",2,"Il mène à un entrepôt précis."],["Demander où il l\u0027a acheté",1,"Un nom de stand, rien de plus."],["Jeter l\u0027emballage",0,"Plus aucune piste."]]},{"t":"Le stand vend les implants à moitié prix.","c":[["Prévenir les clients autour",1,"Les ventes baissent, mais le vendeur se méfie."],["Renverser le stand",0,"Le vendeur s\u0027enfuit avec tout son stock."],["Acheter un implant comme preuve",2,"La puce porte la marque d\u0027une filiale de Kurogane."]]},{"t":"Le fournisseur est une filiale de Kurogane.","c":[["Aller les menacer seul",0,"On te met dehors sans ménagement."],["Transmettre les preuves à Ivana",2,"L\u0027article sortira : tout le Bazar sera prévenu."],["Garder les preuves pour plus tard",1,"Sage, mais les ventes continuent."]]}],"win":"Une filiale de Kurogane. Évidemment. Grâce à toi, le Bazar est prévenu. Mes patients te disent merci, et moi aussi.","lose":"Le fournisseur a fermé boutique avant qu\u0027on le coince, mais ses implants circulent toujours. Il faut recommencer."},"lou":{"intro":"Quelqu\u0027un m\u0027a volé mon dernier morceau ! Il tourne déjà sur une radio corpo. Retrouve le fichier original, c\u0027est ma preuve.","beats":[{"t":"Le morceau passe sur la radio d\u0027un club concurrent.","c":[["Écouter le mix en entier",2,"Une signature audio cachée trahit le voleur."],["Demander au DJ d\u0027arrêter",0,"Il hausse le volume."],["Enregistrer la diffusion",1,"Une preuve, mais incomplète."]]},{"t":"Le voleur est un DJ corpo, protégé par son label.","c":[["Le confronter en public",0,"Le label te fait sortir par la sécurité."],["Pirater le serveur du label",2,"Tu trouves le fichier volé, daté d\u0027après celui de Lou."],["Contacter un avocat",1,"Lent, mais l\u0027affaire est lancée."]]},{"t":"Tu as la preuve. Que faire ?","c":[["Tout publier sur le réseau des clubs",2,"La ville entière sait qui a composé ce morceau."],["Laisser Lou décider",1,"Elle préfère attendre le bon moment."],["Faire chanter le DJ",0,"Lou n\u0027aime pas du tout ces méthodes."]]}],"win":"Le DJ corpo n\u0027aura plus jamais de basses ! Et toute la ville sait que ce son est à moi. T\u0027es un·e vrai·e ami·e.","lose":"On n\u0027a pas pu prouver que le morceau était à moi. Il tourne encore sous son nom. Ça me tue. On réessaie ?"},"okoro":{"intro":"Une vieille affaire me hante depuis quinze ans. Le dossier est resté dans l\u0027ancien commissariat. Récupère-le avant que quelqu\u0027un d\u0027autre ne le fasse.","beats":[{"t":"Le commissariat abandonné est squatté par une bande.","c":[["Négocier l\u0027accès avec leur chef",2,"Il te laisse passer contre un service."],["Entrer par le toit",1,"Discret, mais tu te coupes en passant."],["Les faire fuir en déclenchant l\u0027alarme",0,"Toute la rue rapplique."]]},{"t":"Les archives ont été en partie brûlées.","c":[["Récupérer les fragments un à un",2,"Le dossier est lisible, presque entier."],["Prendre seulement ce qui est intact",1,"Il manque des pages importantes."],["Repartir les mains vides",0,"Tout est perdu pour aujourd\u0027hui."]]},{"t":"Quelqu\u0027un d\u0027autre fouille les archives : un agent de Kurogane.","c":[["Se cacher et le laisser partir",1,"Il repart avec une partie du dossier."],["L\u0027enfermer dans la salle des scellés",2,"Tu repars avec tout, il reste coincé jusqu\u0027au matin."],["L\u0027affronter",0,"Il s\u0027enfuit avec les pages clés."]]}],"win":"Les preuves étaient là depuis le début. Quinze ans que je cherchais. Tu as fait du bon travail, collègue.","lose":"Le dossier est incomplet. Il me manque l\u0027essentiel. On retentera, mais il faudra faire vite."}};
